const READ_NODE_NAMES = [
  'Read Operative Job Sheet1',
  'Read Operative Job Sheet',
];

function sheetRowsFromNode(nodeName) {
  try {
    return $(nodeName).all().map((i) => i.json || {});
  } catch (e) {
    return [];
  }
}

function rowDedupeKey(row) {
  const id = String(row.smart_form_x_id ?? row['smart_form_x_id'] ?? '').trim();
  if (id) return `id::${id}`;
  const rn = String(row.row_number ?? row.rowNumber ?? '').trim();
  if (rn) return `row::${rn}`;
  return null;
}

function collectAllSheetRows() {
  const merged = new Map();
  let seq = 0;

  function addRow(row) {
    if (!row || typeof row !== 'object') return;
    const key = rowDedupeKey(row) || `seq::${seq++}`;
    merged.set(key, row);
  }

  for (const item of $input.all()) {
    addRow(item.json || {});
  }

  for (const nodeName of READ_NODE_NAMES) {
    for (const row of sheetRowsFromNode(nodeName)) {
      addRow(row);
    }
  }

  return [...merged.values()];
}

function isHeaderRow(row) {
  const name = String(row['SmartForm Name'] ?? row.smart_form_name ?? '').trim();
  return /^smartform name$/i.test(name);
}

const rows = collectAllSheetRows();

const skip_smart_form_ids = [];
const skip_entries = [];
const seenIds = new Set();
const seenKeys = new Set();
function normKey(name, dateCreated) {
  return `${String(name || '').trim().toLowerCase().replace(/\s+/g, ' ')}::${String(dateCreated || '').trim()}`;
}

function isBccResponseRepairsName(name) {
  return /:\s*BCC\s+Respon(?:se|sive)\s+Repairs\b/i.test(String(name || '').trim());
}

let dataRowCount = 0;

for (const row of rows) {
  if (isHeaderRow(row)) continue;
  dataRowCount++;

  const id = String(row.smart_form_x_id ?? row['smart_form_x_id'] ?? '').trim();
  if (id) {
    if (!seenIds.has(id)) {
      seenIds.add(id);
      skip_smart_form_ids.push(id);
    }
  }
  const name =
    row['SmartForm Name'] ?? row.smart_form_name ?? row.form_name ?? row['SmartForm name'] ?? '';
  const dateCreated =
    row['Date Created'] ?? row.date_created ?? row['Date created'] ?? '';
  if (name && dateCreated) {
    const key = normKey(name, dateCreated);
    if (!seenKeys.has(key)) {
      seenKeys.add(key);
      skip_entries.push({
        smart_form_name: String(name).trim(),
        date_created: String(dateCreated).trim(),
      });
    }
  }

}

return [
  {
    json: {
      skip_smart_form_ids,
      skip_entries,
      sheet_row_count: dataRowCount,
      sheet_items_read: rows.length,
      sheet_skip_id_count: skip_smart_form_ids.length,
      sheet_skip_entry_count: skip_entries.length,
    },
  },
];

