function extractApiBody(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {
      const m = body.match(/\{[\s\S]*\}/);
      if (m) {
        try { body = JSON.parse(m[0]); } catch (e2) { body = {}; }
      } else {
        body = {};
      }
    }
  }
  if (
    body &&
    typeof body === 'object' &&
    body.body &&
    body.results === undefined &&
    body.total_extracted === undefined
  ) {
    body = body.body;
  }
  return { statusCode, body: body || {} };
}

function normText(v) {
  return String(v ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normDate(v) {
  return String(v ?? '').trim();
}

function dupKey(name, dateCreated) {
  return `${normText(name)}::${normDate(dateCreated)}`;
}

function isBccResponseRepairsName(name) {
  return /:\s*BCC\s+Respon(?:se|sive)\s+Repairs\b/i.test(String(name || '').trim());
}

const Q21_DESC_COL = 'Q2.1 Daily Jobs Table';
const Q21_PRICE_COL = 'Q2.1 Daily Jobs Table Price/Hours';

function addLabeledFields(target, parsed) {
  const labeled = parsed.labeled_fields || {};
  const fields = parsed.fields || {};
  for (const [col, val] of Object.entries(labeled)) {
    if (val == null) continue;
    if (Array.isArray(val) || (typeof val === 'object' && val !== null)) {
      const text = JSON.stringify(val);
      if (text && text !== '[]' && text !== '{}') target[col] = text;
      continue;
    }
    const text = String(val).trim();
    if (col === Q21_PRICE_COL || text) target[col] = text;
  }
  if (Q21_DESC_COL in labeled || fields['Q2.1_description'] != null || fields['Q2.1_table']) {
    if (target[Q21_DESC_COL] == null) {
      target[Q21_DESC_COL] = String(labeled[Q21_DESC_COL] ?? fields['Q2.1_description'] ?? '').trim();
    }
    if (target[Q21_PRICE_COL] == null) {
      target[Q21_PRICE_COL] = String(
        labeled[Q21_PRICE_COL] ?? fields['Q2.1_price_hours'] ?? fields['Q2.1_table']?.price_hours ?? ''
      ).trim();
    }
  }
}

function applyPhotoYesNo(target, parsed) {
  const photos = parsed.photos || {};
  const completed = Array.isArray(photos.completed_work) ? photos.completed_work.length : 0;
  const variations = Array.isArray(photos.variations) ? photos.variations.length : 0;
  let hasQ23 = false;
  let hasQ26 = false;
  for (const k of Object.keys(target)) {
    if (/^Q2\.3\b/i.test(k)) {
      target[k] = completed > 0 ? 'Yes' : 'No';
      hasQ23 = true;
    }
    if (/^Q2\.6\b/i.test(k)) {
      target[k] = variations > 0 ? 'Yes' : 'No';
      hasQ26 = true;
    }
  }
  if (!hasQ23) {
    target['Q2.3 Please provide photos of completed work'] = completed > 0 ? 'Yes' : 'No';
  }
  if (!hasQ26) {
    target['Q2.6 Please provide photos of variations'] = variations > 0 ? 'Yes' : 'No';
  }
}

function corfFromQ11Address(addr) {
  const s = String(addr ?? '').trim();
  const m = s.match(/-(\d+\/\d+)\s*$/);
  return m ? m[1] : '';
}

const existingRows = $('Read Operative Job Sheet').all().map((i) => i.json || {});
const skipPayload = (() => {
  for (const name of ['Build skip payload from sheet1', 'Build skip payload from sheet']) {
    try {
      const j = $(name).first()?.json;
      if (j && (j.skip_entries || j.skip_smart_form_ids)) return j;
    } catch (e) {}
  }
  return {};
})();
const existingKeys = new Set();
const existingIds = new Set();
for (const id of skipPayload.skip_smart_form_ids || []) {
  const sid = String(id || '').trim();
  if (sid) existingIds.add(sid);
}
for (const entry of skipPayload.skip_entries || []) {
  const name = entry.smart_form_name || entry.form_name || '';
  const dateCreated = entry.date_created || '';
  if (name && dateCreated) existingKeys.add(dupKey(name, dateCreated));
}

for (const row of existingRows) {
  const name =
    row['SmartForm Name'] ?? row.smart_form_name ?? row.form_name ?? row['SmartForm name'] ?? '';
  const dateCreated =
    row['Date Created'] ?? row.date_created ?? row['Date created'] ?? '';
  if (name && dateCreated) {
    existingKeys.add(dupKey(name, dateCreated));
  }
  const id = String(row.smart_form_x_id ?? row['smart_form_x_id'] ?? '').trim();
  if (id) existingIds.add(id);
}

const respRaw = $('POST extract-operative-job-sheets').first().json || {};
const { statusCode, body } = extractApiBody(respRaw);
const results = Array.isArray(body.results) ? body.results : [];
const errors = Array.isArray(body.errors) ? body.errors : [];

const out = [];
let skippedDuplicate = 0;
let skippedNoName = 0;
let skippedNonBcc = 0;
for (const r of results) {
  const grid = r.grid || {};
  const cells = grid.cells || {};
  const parsed = r.parsed || {};

  const smartFormName =
    grid.form_name || cells.list_form_name || parsed.job_header || '';
  const dateCreated = grid.date_created || cells.list_date_created || '';
  const sfid = String(r.smart_form_x_id || '').trim();

  if (!smartFormName || !dateCreated) {
    skippedNoName++;
    continue;
  }

  if (!isBccResponseRepairsName(smartFormName)) {
    skippedNonBcc++;
    continue;
  }

  if (sfid && existingIds.has(sfid)) {
    skippedDuplicate++;
    continue;
  }

  // Only fall back to name+date when EasyBOP id is missing (legacy rows).
  if (!sfid && existingKeys.has(dupKey(smartFormName, dateCreated))) {
    skippedDuplicate++;
    continue;
  }

  existingKeys.add(dupKey(smartFormName, dateCreated));
  if (sfid) existingIds.add(sfid);

  const row = {
    smart_form_x_id: sfid,
    'SmartForm Name': String(smartFormName).trim(),
    'Date Created': normDate(dateCreated),
    'SmartForm Template Name':
      grid.template_name || cells.list_template_name || parsed.template_title || '',
    Status: grid.status || cells.list_status || 'Complete',
    'Completed Date': grid.date_completed || cells.list_date_completed || '',
    'Completed Time': grid.time_completed || cells.list_time_completed || '',
    'Created By': grid.created_by || cells.list_created_by || '',
    Module: grid.module_name || cells.list_module_name || '',
    CORF: '',
    'Job Header': parsed.job_header || '',
    pdf_url: r.pdf_url || '',
    extracted_at: new Date().toISOString(),
  };

  addLabeledFields(row, parsed);
  applyPhotoYesNo(row, parsed);
  row.CORF = corfFromQ11Address(row['Q1.1 Address']) || parsed.corf || '';


  out.push({ json: row });
}

if (!out.length) {
  return [
    {
      json: {
        _skip_append: true,
        message:
          results.length > 0
            ? `All ${results.length} extracted row(s) skipped (duplicate or missing name/date).`
            : statusCode >= 400
              ? `API HTTP ${statusCode}: ${body.detail || body.message || 'extract failed'}`
              : body.total_skipped_existing > 0
                ? `No new rows — ${body.total_skipped_existing} already on sheet (${body.total_grid_matched || 0} on EasyBOP).`
                : 'No new Operative job sheets to append',
        api_status: statusCode,
        partial: body.partial === true,
        total_extracted: body.total_extracted ?? results.length,
        total_errors: body.total_errors ?? errors.length,
        total_skipped_existing: body.total_skipped_existing ?? 0,
        total_grid_matched: body.total_grid_matched ?? 0,
        skipped_duplicate: skippedDuplicate,
        skipped_missing_name_or_date: skippedNoName,
        skipped_non_bcc_response_repairs: skippedNonBcc,
                appended_count: 0,
      },
    },
  ];
}

return out.map((item, idx) => ({
  json: {
    ...item.json,
    _skip_append: false,
    ...(idx === 0
      ? {
          api_status: statusCode,
          partial: body.partial === true,
          total_extracted: body.total_extracted ?? results.length,
          total_errors: body.total_errors ?? errors.length,
          total_skipped_existing: body.total_skipped_existing ?? 0,
          total_grid_matched: body.total_grid_matched ?? 0,
          skipped_duplicate: skippedDuplicate,
          skipped_missing_name_or_date: skippedNoName,
          skipped_non_bcc_response_repairs: skippedNonBcc,
                    appended_count: out.length,
        }
      : {}),
  },
}));

const META = new Set([
  '_skip_append',
  'api_status',
  'total_extracted',
  'total_errors',
  'skipped_duplicate',
  'skipped_missing_name_or_date',
  'skipped_non_bcc_response_repairs',
  'appended_count',
  'message',
  'sort_row_count',
  'partial',
  'total_skipped_existing',
  'total_grid_matched',
]);

return $input.all().map((item) => {
  const clean = {};
  for (const [k, v] of Object.entries(item.json || {})) {
    if (k.startsWith('_') || META.has(k)) continue;
    clean[k] = v;
  }
  return { json: clean };
});

const META = new Set([
  '_skip_append',
  'api_status',
  'total_extracted',
  'total_errors',
  'total_skipped_existing',
  'total_grid_matched',
  'partial',
  'skipped_duplicate',
  'skipped_missing_name_or_date',
  'skipped_non_bcc_response_repairs',
  'appended_count',
  'message',
  'sort_row_count',
]);

function smartFormName(row) {
  return String(row['SmartForm Name'] ?? row.smart_form_name ?? '').trim();
}

function dateCreated(row) {
  return String(row['Date Created'] ?? row.date_created ?? row['Date created'] ?? '').trim();
}

function isHeaderRow(row) {
  return /^smartform name$/i.test(smartFormName(row));
}

function isBccResponseRepairsName(name) {
  return /:\s*BCC\s+Respon(?:se|sive)\s+Repairs\b/i.test(String(name || '').trim());
}

function isDataRow(row) {
  const name = smartFormName(row);
  return Boolean(name) && !isHeaderRow(row) && isBccResponseRepairsName(name);
}

function rowsFromNode(nodeName) {
  try {
    return $(nodeName).all().map((i) => i.json || {});
  } catch (e) {
    return [];
  }
}

function stripMeta(row) {
  const clean = {};
  for (const [k, v] of Object.entries(row || {})) {
    if (k.startsWith('_') || META.has(k)) continue;
    clean[k] = v;
  }
  return clean;
}

function rowKey(row, idx) {
  const id = String(row.smart_form_x_id ?? row['smart_form_x_id'] ?? '').trim();
  if (id) return `id::${id}`;
  const rn = String(row.row_number ?? row.rowNumber ?? '').trim();
  if (rn) return `row::${rn}`;
  return `fallback::${smartFormName(row).toLowerCase()}::${dateCreated(row)}::${idx}`;
}

function parseUkDate(s) {
  const raw = String(s ?? '').trim();
  if (!raw) return 0;
  const m = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (!m) return 0;
  let yr = parseInt(m[3], 10);
  if (yr < 100) yr += 2000;
  const hh = parseInt(m[4] || '0', 10);
  const mm = parseInt(m[5] || '0', 10);
  const ss = parseInt(m[6] || '0', 10);
  return new Date(yr, parseInt(m[2], 10) - 1, parseInt(m[1], 10), hh, mm, ss).getTime();
}

// Merge sheet read + newly formatted rows.
// Clean rows for sheet (carries photo URLs) MUST be last so it wins.
const PHOTO_COLS = [
  'Q2.3 Please provide photos of completed work',
  'Q2.6 Please provide photos of variations ( if Variation was yes)',
  'Q2.6 Please provide photos of variations',
];
function isRealUrl(v) {
  return typeof v === 'string' && /^https?:\/\//i.test(v.trim());
}

const merged = new Map();
let seq = 0;
const sources = [
  ...rowsFromNode('Read sheet for sort'),
  ...rowsFromNode('Read sheet for sort1'),
  ...rowsFromNode('Read Operative Job Sheet1'),
  ...rowsFromNode('Read Operative Job Sheet'),
  ...rowsFromNode('Format rows and skip duplicates')
    .filter((r) => r._skip_append !== true)
    .map(stripMeta),
  ...rowsFromNode('Format rows and skip duplicates1')
    .filter((r) => r._skip_append !== true)
    .map(stripMeta),
  ...rowsFromNode('Clean rows for sheet'),
  ...rowsFromNode('Clean rows for sheet1'),
];

for (const row of sources) {
  if (!isDataRow(row)) continue;
  const key = rowKey(row, seq++);
  const prev = merged.get(key);
  if (!prev) {
    merged.set(key, { ...row });
    continue;
  }
  const next = { ...prev, ...row };
  // Never let an empty/absent photo URL clobber a real one already collected
  for (const col of PHOTO_COLS) {
    if (isRealUrl(prev[col]) && !isRealUrl(next[col])) {
      next[col] = prev[col];
    }
  }
  merged.set(key, next);
}

const rows = [...merged.values()];

rows.sort((a, b) => {
  const nameA = smartFormName(a).toLowerCase();
  const nameB = smartFormName(b).toLowerCase();
  if (nameA !== nameB) {
    return nameA.localeCompare(nameB, undefined, { numeric: true, sensitivity: 'base' });
  }
  return parseUkDate(dateCreated(b)) - parseUkDate(dateCreated(a));
});

return rows.map((row, idx) => ({
  json: {
    ...row,
    ...(idx === 0 ? { sort_row_count: rows.length } : {}),
  },
}));

const META = new Set(['sort_row_count']);

return $('Sort by SmartForm Name + Date').all().map((item) => {
  const clean = {};
  for (const [k, v] of Object.entries(item.json || {})) {
    if (META.has(k)) continue;
    clean[k] = v;
  }
  return { json: clean };
});

function safeFirst(nodeName) {
  try {
    return $(nodeName).first()?.json || {};
  } catch (e) {
    return {};
  }
}

function safeAllCount(nodeName) {
  try {
    return $(nodeName).all().length;
  } catch (e) {
    return 0;
  }
}

const formatFirst = safeFirst('Format rows and skip duplicates');
const appendedFromFormat = Number(formatFirst.appended_count);
const appended =
  Number.isFinite(appendedFromFormat) && appendedFromFormat > 0
    ? appendedFromFormat
    : safeAllCount('Clean rows for sheet');

const skipped = formatFirst.skipped_duplicate ?? 0;
const skippedNonBcc = formatFirst.skipped_non_bcc_response_repairs ?? 0;
const skippedExisting = formatFirst.total_skipped_existing ?? 0;
const skippedTotal = skipped + skippedExisting;
const totalExtracted = formatFirst.total_extracted ?? null;
const totalErrors = formatFirst.total_errors ?? null;
const gridMatched = formatFirst.total_grid_matched ?? null;
const apiStatus = formatFirst.api_status ?? null;
const skipAppend = formatFirst._skip_append === true;
const sortedRowCount = Number(safeFirst('Sort by SmartForm Name + Date').sort_row_count) || safeAllCount('Sort by SmartForm Name + Date');

let message = formatFirst.message || '';
if (!message) {
  if (skipAppend) {
    message =
      totalExtracted > 0
        ? `No new rows appended (${totalExtracted} extracted, ${skippedTotal} skipped).`
        : 'No rows appended.';
  } else if (appended > 0) {
    message = `Appended ${appended} Operative job sheet row(s).`;
  } else {
    message = 'Run finished.';
  }
}
if (sortedRowCount > 0) {
  message += ` Sheet re-sorted (${sortedRowCount} row(s) grouped by SmartForm Name).`;
}
if (skippedNonBcc > 0) {
  message += ` Skipped ${skippedNonBcc} non-BCC Response Repairs row(s).`;
}

return [
  {
    json: {
      ok: appended > 0 || (totalExtracted > 0 && !skipAppend) || sortedRowCount > 0,
      message,
      appended_count: appended,
      sorted_row_count: sortedRowCount,
      skipped_duplicate: skipped,
      skipped_non_bcc_response_repairs: skippedNonBcc,
      skipped_existing: skippedExisting,
      skipped_total: skippedTotal,
      total_grid_matched: gridMatched,
      total_extracted: totalExtracted,
      total_errors: totalErrors,
      api_status: apiStatus,
      partial: formatFirst.partial === true,
    },
  },
];
